def index(document, store):
    chunks = chunk(document.text, size=800, overlap=100)
    vectors = embed_batch(chunks)                  # one forward pass per chunk

    store.upsert([
        {"doc_id": document.id, "text": c, "vector": v}
        for c, v in zip(chunks, vectors)
    ])

